# frozen_string_literal: true
# rbs_inline: enabled

# Run from the directory generated by prepare_mir_generation_profile.rb.
# No cache, snapshot, MIR execution profiling, or exported guest execution.
require_relative "measurement"
require "pp"
# Spinel resolves requires statically; preload method-local dependencies.
# CRuby needs ValueHelper defined before loading the WASI class.
require "wardite/value" if RUBY_ENGINE != "spinel"
require "wardite/wasi"
require "wardite"

started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
instance = File.open(ARGV.fetch(0), "rb") do |file|
  Wardite::BinaryLoader.load_from_buffer(file, engine: :efflorescence,
    disabled_optimizations: ARGV[1] == "no-inline" ? [:inline] : [])
end
elapsed = Process.clock_gettime(Process::CLOCK_MONOTONIC) - started
raise "Use a fixture without a start section" if instance.start_section
puts "total,#{elapsed},1"
MirGenerationMeasurement::NAMES.each_with_index do |name, index|
  puts "#{name},#{MirGenerationMeasurement::SECONDS[index]},#{MirGenerationMeasurement::COUNTS[index]}"
end

vm = instance.runtime
raise "Expected MIR VM" unless vm.is_a?(Wardite::Efflorescence::VM)
instructions = 0
registers = 0
eligible = 0
eligible_instructions = 0
max_registers = 0
vm.semantic_ir.functions.each do |function|
  instructions += function.instructions.size
  registers += function.register_count
  max_registers = function.register_count if function.register_count > max_registers
  unless function.uses_i64 || function.uses_float || function.uses_eh || function.uses_store || function.uses_dynamic_calls
    eligible += 1
    eligible_instructions += function.instructions.size
  end
end
optimized_instructions = 0
vm.ir.functions.each { |function| optimized_instructions += function.instructions.size }
puts "functions,#{vm.ir.functions.size},0"
puts "instructions,#{instructions},0"
puts "optimized_instructions,#{optimized_instructions},0"
puts "registers,#{registers},0"
puts "max_registers,#{max_registers},0"
puts "eligible_functions,#{eligible},0"
puts "eligible_instructions,#{eligible_instructions},0"
